
import React, { useRef, forwardRef, useImperativeHandle, useState } from "react";

import { SvgIcon_Cmpt } from ".";

import "./ContainerElasticView.css";
import { useRefComputed } from "../hooks/useObjects";

const Svg = SvgIcon_Cmpt();




function ContainerElasticView({children}) {
    
  const iconRef = useRef(false);
  const boxRef = useRef(false);


  const drawBox=(e)=>{
    boxRef?.current?.setAttribute("show",e);
    iconRef.current.refresh(e?"key_arrow_up":"key_arrow_down");
  }

	const countR = useRefComputed(false, drawBox);



  
	return (
		<div>
      <div className={`elastic_view_bx`} ref={boxRef} >
        <div className={`wrapp`} >
          {children}
        </div>
      </div>
      <div>
        <div 
          className="icon_revision" 
          style={{cursor:"pointer"}}
          onClick={()=>{
            countR.value =! countR.value;
          }}
        >
          <SvgRef
            ref={iconRef}
          />
        </div>
      </div>
		</div>
	);
}



export default ContainerElasticView;



const SvgRef = forwardRef(({  }, ref) => {

  const [icon, setIcon] = useState("key_arrow_down");
	
  useImperativeHandle(ref, () => ({
		refresh(v) {
			setIcon(v);
		}
	}));
  

  return 	<Svg
            name={icon} 
            color={"var(--light-300)"}
          />;
})















